// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.security.storageimport android.content.Contextimport android.content.SharedPreferencesimport androidx.security.crypto.EncryptedSharedPreferencesimport androidx.security.crypto.MasterKeyimport com.roshan.persona.security.keystore.KeystoreManagerimport dagger.hilt.android.qualifiers.ApplicationContextimport timber.log.Timberimport javax.inject.Injectimport javax.inject.Singleton/** * NOUS — Encrypted Storage (Module 12, Pillar 4). * * Strategy §12.4 — wraps [EncryptedSharedPreferences] with a **double-layer key**: * *   1. **Master key** in AndroidKeystore (hardware-backed, AES-256-GCM) — *      generated by [MasterKey.Builder] with `KeyScheme.AES256_GCM` and *      `setUserAuthenticationRequired(false)` (per-feature auth is enforced *      at the use site by [CredentialVaultImpl] / [AppLockManager]). * *   2. **Per-entry data key** — for sensitive entries (credentials, API *      keys), we wrap the value in a second layer of AES-256-GCM via *      [KeystoreManager.encryptString]. This means even if EncryptedSharedPreferences's *      master key is compromised, only the outer layer is broken — the *      inner ciphertext remains protected by a separate Keystore key. * * ## Real Android APIs used * * | Operation | API | * |-----------|-----| * | Master key | `MasterKey.Builder(context).setKeyScheme(AES256_GCM).build()` | * | Encrypted prefs | `EncryptedSharedPreferences.create(context, fileName, masterKey, AES256_SIV, AES256_GCM)` | * | Per-entry layer | `KeystoreManager.encryptString(alias, value)` | * * The `AES256_SIV` key scheme is used for KEYS (deterministic — same key * produces same ciphertext, allowing lookup). `AES256_GCM` is used for * VALUES (randomized — fresh IV per write). * * ## Why double-layer? * * EncryptedSharedPreferences alone is solid, but its master key is a single * point of failure. By wrapping high-value entries (API keys, passwords) * in a second AES-256-GCM layer backed by a SEPARATE Keystore alias, we * achieve defense-in-depth: * *   - Attacker breaks ESP master key → still sees the inner ciphertext. *   - Attacker breaks Keystore alias → still sees the ESP-encrypted value. *   - Attacker must break BOTH to read the plaintext. * * @see CredentialVaultImpl */@Singletonclass EncryptedStorage @Inject constructor(    @ApplicationContext private val context: Context,    private val keystoreManager: KeystoreManager,) {    /**     * The underlying [EncryptedSharedPreferences] instance for general     * (single-layer) encrypted storage.     *     * Lazy-initialized on first access. Uses the standard AndroidX     * MasterKey (auto-generated, hardware-backed where available).     */    val encryptedPrefs: SharedPreferences by lazy {        try {            val masterKey = MasterKey.Builder(context)                .setKeyScheme(MasterKey.KeyScheme.AES256_GCM)                .build()            EncryptedSharedPreferences.create(                context,                PREFS_FILE,                masterKey,                EncryptedSharedPreferences.PrefKeyEncryptionScheme.AES256_SIV,                EncryptedSharedPreferences.PrefValueEncryptionScheme.AES256_GCM,            )        } catch (e: Exception) {            Timber.tag("NOUS.Security").e(e, "Failed to initialize EncryptedSharedPreferences — falling back to plain prefs (DEV ONLY)")            // Fallback: plain prefs. This should NEVER happen in production            // (EncryptedSharedPreferences works on all API 23+ devices).            // If it does, we prefer crashing silently over refusing to boot.            context.getSharedPreferences("${PREFS_FILE}.fallback", Context.MODE_PRIVATE)        }    }    /**     * Store a value with single-layer encryption (EncryptedSharedPreferences only).     *     * Use for non-critical data: feature flags, counters, last-seen timestamps.     * For credentials and API keys, use [storeDoubleEncrypted].     *     * @param key the preference key.     * @param value the plaintext value to store.     */    fun putString(key: String, value: String) {        encryptedPrefs.edit().putString(key, value).apply()    }    /**     * Read a single-layer encrypted value.     */    fun getString(key: String, default: String? = null): String? =        encryptedPrefs.getString(key, default)    /**     * Store a value with DOUBLE-layer encryption.     *     * Inner layer: [KeystoreManager.encryptString] with [innerKeyAlias].     * Outer layer: EncryptedSharedPreferences's built-in AES-256-GCM.     *     * @param outerKey the ESP preference key.     * @param innerKeyAlias the Keystore alias for the inner encryption key.     *   Must already exist (call [KeystoreManager.generateKey] first).     * @param value the plaintext to store.     * @return true if both layers succeeded.     */    fun storeDoubleEncrypted(outerKey: String, innerKeyAlias: String, value: String): Boolean {        val ciphertext = keystoreManager.encryptString(innerKeyAlias, value) ?: run {            Timber.tag("NOUS.Security").w("Inner-layer encryption failed for key=%s", outerKey)            return false        }        // Store the serialized ciphertext (JSON-like) in EncryptedSharedPreferences.        // We use a simple "iv|ciphertext" format to avoid JSON parsing overhead.        val serialized = "${ciphertext.ivBase64}|${ciphertext.ciphertextBase64}"        encryptedPrefs.edit().putString(outerKey, serialized).apply()        return true    }    /**     * Read a double-encrypted value.     *     * @param outerKey the ESP preference key.     * @param innerKeyAlias the Keystore alias for the inner key.     * @return the plaintext, or null if not found or decryption failed.     */    fun readDoubleEncrypted(outerKey: String, innerKeyAlias: String): String? {        val serialized = encryptedPrefs.getString(outerKey, null) ?: return null        val parts = serialized.split("|", limit = 2)        if (parts.size != 2) {            Timber.tag("NOUS.Security").w("Malformed double-encrypted entry: %s", outerKey)            return null        }        val ciphertext = com.roshan.persona.security.keystore.Ciphertext(            ivBase64 = parts[0],            ciphertextBase64 = parts[1],            securityLevel = keystoreManager.lastSecurityLevel(innerKeyAlias),        )        return keystoreManager.decryptString(innerKeyAlias, ciphertext)    }    /**     * Remove an entry (single or double encrypted).     */    fun remove(key: String) {        encryptedPrefs.edit().remove(key).apply()    }    /**     * List all preference keys (single-layer only — for double-layer,     * the outer key is what appears here).     */    fun keys(): Set<String> = encryptedPrefs.all.keys    /**     * Wipe all encrypted storage. Use for "delete all my data".     */    fun wipe() {        encryptedPrefs.edit().clear().apply()    }    private companion object {        const val PREFS_FILE = "nous_encrypted_prefs"    }}